window.PORTFOLIO_DATA={"projects":[{"id":"hospital","number":"01","title":"Hospital ER Analytics","tool":"Power BI","types":["analytics"],"kind":"Healthcare dataset","image":"assets/hospital.png","alt":"Original Power BI department performance dashboard with referral counts, wait-time and satisfaction summaries.","cover":"Power BI / Original dashboard","question":"How do patient volume and referrals vary across departments?","subtitle":"Understanding patient flow through an interactive Power BI report.","tools":["Power BI","DAX","Power Query","Data modeling"],"repo":"https://github.com/Basit52692/Hospital-Executive-Summary-PowerBI","file":"https://basit52692.github.io/Basit-Hussain-Portfolio/assets/Hospital_Data_Analysis.pbix","fileLabel":"Power BI file","sourceLabel":"Public CSV + original Power BI screenshot","chart":"hospital","overview":["A multi-page Power BI report exploring patient volume, department referrals, waiting times, satisfaction and demographics. The aim is to make service patterns easier to investigate.","The project is analytical and descriptive. The portfolio does not claim that the dashboard reduced waiting times or changed hospital outcomes."],"dataset":["The repository CSV contains <strong>9,216 records</strong>, dated <strong>01 Apr 2019 to 30 Oct 2020</strong>. This prototype uses aggregate counts only; patient names and identifiers are not embedded.","Fields include date, referral department, age, gender, wait time and satisfaction score. The repository does not document the original data provenance, collection process or wait-time unit.","Only <strong>2,517 of 9,216 records</strong> contain a satisfaction score. A mean satisfaction score therefore does not describe every visit."],"method":["The source project uses Power Query, data modeling and DAX to produce executive, department and demographic report pages.","For this prototype, referral counts were independently aggregated from the repository CSV and checked against the dashboard total.","The interactive comparison below lets you include or exclude the source value “None”. Named department rankings should be read separately from this larger no-referral group.","The PBIX report measures were not executed during this design review; this page distinguishes recalculated CSV counts from the original report image."],"findings":[{"title":"5,400 records have no department referral.","body":"The literal source value “None” accounts for 58.59% of the 9,216 records. It should not be silently mixed into a named-department ranking."},{"title":"General Practice is the largest named referral group.","body":"It contains 1,840 records, followed by Orthopedics with 995. These are descriptive counts, not a measure of department quality."},{"title":"Satisfaction has substantial missingness.","body":"6,699 records have no satisfaction score. Any satisfaction comparison needs a reported denominator and a missingness caveat."}],"value":["The report provides a starting point for questions about patient mix and service demand. Referral volumes can help prioritize a deeper capacity review.","No measured operational impact has been established. Staffing or clinical decisions would require validated definitions, context and further analysis."],"limits":["The meaning of a record, original data provenance and wait-time unit need confirmation before public analytical claims.","Referral volume does not measure staffing demand, service quality or clinical need by itself.","Satisfaction scores are incomplete. Missingness may not be random."],"source":"https://github.com/Basit52692/Hospital-Executive-Summary-PowerBI/blob/main/Hospital%20ER.csv"},{"id":"leads","number":"02","title":"Business Lead Data Pipeline","tool":"Python","types":["automation"],"kind":"Synthetic demo","image":"assets/leads.png","alt":"Original Business Lead Data Pipeline demo Excel report showing 168 raw records, 150 unique records and 54 potential leads.","cover":"Python / Original Excel output","question":"How can inconsistent listings become a reviewable dataset?","subtitle":"From local demo pages to clean records, quality flags and an Excel report.","tools":["Python","pandas","BeautifulSoup","Selenium template","OpenPyXL"],"repo":"https://github.com/Basit52692/Business-Lead-Data-Pipeline","file":"https://basit52692.github.io/Basit-Hussain-Portfolio/assets/Business_Lead_Data_Extraction_Validation_Pipeline.zip","fileLabel":"Project archive","sourceLabel":"Synthetic raw/processed CSV + source code","chart":"leads","overview":["Raw business listings can contain inconsistent formatting, missing fields and duplicates. This project demonstrates a repeatable collection, standardization, validation and reporting workflow.","Every record is synthetic. The public project contains no employer or client data; “potential lead” is a classification rule rather than a verified commercial opportunity."],"dataset":["The bundled sample site has four local HTML pages. The supplied raw CSV has <strong>168 records</strong>; the processed CSV has <strong>150 records</strong>.","The prototype was checked against both CSVs and <code>outputs/summary.json</code>. Displayed values are project outputs, not client or employer performance metrics."],"method":["Extract the demo listings from bundled HTML with BeautifulSoup. A separate Selenium template shows how a dynamic extraction layer could be adapted.","Normalize whitespace, business names, phone numbers, website values, email casing and locations.","Deduplicate by normalized name and phone; use name, city and category as a fallback when phone is missing.","Validate missing phone, website and address; check basic email structure. Preserve quality flags and calculate completeness across seven core fields.","Apply classification in the source-code order: website missing + phone available → Potential Lead; otherwise missing phone or address → Needs Review; remaining rows → Existing Website.","Export a processed CSV, a JSON summary and a multi-sheet Excel report."],"findings":[{"title":"18 duplicate records are removed.","body":"The supplied raw and processed outputs reconcile from 168 to 150 records."},{"title":"54 records meet the potential-lead rule.","body":"These records lack a website and have a phone number. This is prioritization logic, not evidence of interest or conversion."},{"title":"18 records need review; 78 have an existing website status.","body":"These exclusive status counts sum with the 54 potential leads to 150 processed records. Separate quality flags must still be reviewed."}],"value":["A structured report gives a reviewer consistent fields, explicit statuses and a traceable quality-check process.","The prototype demonstrates how that process can be explained visually without exposing names or contact fields. No time savings, revenue or conversion uplift is asserted."],"limits":["All data are synthetic; this is a workflow demonstration.","Potential-lead classification is evaluated before the review rule. A potential lead can still have an address-related quality flag.","Basic email-format validation does not verify deliverability. Website availability is not a live audit."],"source":"https://github.com/Basit52692/Business-Lead-Data-Pipeline/blob/main/outputs/summary.json"},{"id":"excel","number":"03","title":"Sales & Profitability","tool":"Excel","types":["analytics"],"kind":"Retail practice data","image":"assets/excel.png","alt":"Original Excel sales and profitability dashboard, filtered to 2022, with sales, margin, orders, region and discount charts.","cover":"Excel / Original workbook screenshot","question":"Which sales patterns deserve a closer look?","subtitle":"A readable reporting layer for sales, profitability and commercial questions.","tools":["Excel","XLOOKUP","SUMIFS","Data validation","Charts"],"repo":"https://github.com/Basit52692/Excel-Sales-Performance-Dashboard","file":"https://basit52692.github.io/Basit-Hussain-Portfolio/assets/Sales_Performance_Dashboard.xlsx","fileLabel":"Excel workbook","sourceLabel":"Original workbook screenshot + shared retail dataset","chart":"retail","overview":["An Excel reporting project covering sales, profit, margin, order volume, regional performance, product contribution and discount levels.","The dashboard supports year, region and category selections. Its screenshot is filtered to 2022, while the interactive yearly comparison below includes the full 2019–2022 period."],"dataset":["The workbook Data sheet contains <strong>10,000 practice retail records</strong>. Its order IDs and sales, profit, quantity and discount values match the companion CSV used for the yearly comparison. The workbook data was inspected without executing Excel formulas.","Monetary values are in <strong>source currency units</strong>; the currency is not documented. Figures should not be labelled as dollars or rupees."],"method":["The source portfolio lists formula-based analysis with XLOOKUP and SUMIFS, validation controls, KPI reporting and charts.","The original screenshot shows selected-year sales, prior-year comparison, discount margins, region/category summaries and product contribution.","For this design prototype, the yearly interactive chart is recalculated from the companion CSV. Workbook formulas and live slicer behavior have not been rerun in Excel."],"findings":[{"title":"2022 sales are 2,535,711.07 source units.","body":"The independently aggregated companion CSV shows a 3.36% increase from 2021. The dashboard screenshot rounds sales to 2.54M and growth to 3.4%."},{"title":"2022 and full-period margin have different denominators.","body":"2022 margin is about 17.27%; the 2019–2022 overall margin is 17.05%. Filter context must stay visible beside the KPI."},{"title":"Loss-making orders remain part of the analysis.","body":"The companion dataset contains 79 negative-profit orders over the full period. They are valid outcomes to inspect, not automatically discard."}],"value":["A compact workbook view helps a reader move from a top-level KPI to the relevant year, region or category.","Business value here is a proposed use of the reporting artifact. No measured client improvement is claimed."],"limits":["This is a practice dataset. Original commercial provenance and currency are not documented.","Unique customer and product IDs prevent valid repeat-purchase or true SKU retention claims.","The original screenshot and companion CSV are inspected evidence; Excel formula execution was outside this prototype review."],"source":"https://basit52692.github.io/Basit-Hussain-Portfolio/assets/Sales_Performance_Dashboard.xlsx"},{"id":"sql","number":"04","title":"SQL Sales Analysis","tool":"SQL","types":["analytics"],"kind":"Retail practice data","image":null,"alt":"Actual SQL excerpt from the monthly sales trend analysis.","cover":"PostgreSQL / Source query","question":"Where are sales growing, and where is margin under pressure?","subtitle":"Business questions translated into transparent, reusable PostgreSQL queries.","tools":["PostgreSQL","CTEs","LAG","DENSE_RANK","Window functions"],"repo":"https://github.com/Basit52692/SQL-Sales-Analysis","file":"https://basit52692.github.io/Basit-Hussain-Portfolio/assets/SQL_Sales_Analysis_Professional.zip","fileLabel":"SQL project","sourceLabel":"Original SQL scripts + independently aggregated CSV","chart":"retail","overview":["A nine-file SQL workflow covering setup, data quality, KPIs, trends, product/category performance, regions, discounts and window-function analysis.","The central question is which products, regions and discount levels contribute to sales and profit, and where profitability is under pressure."],"dataset":["The supplied CSV contains <strong>10,000 retail orders from 2019–2022</strong>. It matches the Python project CSV record for record.","Order, customer and product identifiers are all unique in this snapshot. Product analysis therefore uses product names, sub-categories and categories rather than repeat-customer assumptions."],"method":["Define the schema and import the CSV; inspect duplicates, missingness, identifier grain and date consistency.","Aggregate sales and profit at monthly, yearly, category and region levels. Guard ratio denominators with NULLIF.","Use CTEs and LAG for period comparisons, DENSE_RANK for ranked summaries and window aggregates for running totals and moving averages.","The source SQL is displayed below. For this prototype, aggregates are independently checked from the CSV; no PostgreSQL database was executed."],"findings":[{"title":"Overall margin is 17.05%.","body":"10,033,715.95 sales and 1,711,180.34 profit in source units reconcile with the supplied CSV."},{"title":"2022 sales grow 3.36% over 2021.","body":"The interactive comparison uses 2,535,711.07 source units in 2022 and 2,453,286.96 in 2021."},{"title":"Discount and margin are associated in this dataset.","body":"The published grouped output shows 20.35% margin at 0% discount and 13.99% at 30%. This does not isolate a causal discount effect."}],"value":["Reusable queries make analytical definitions inspectable and help another analyst reproduce a reporting question.","The work supports discussion of commercial patterns; it does not establish that changing a discount policy would produce a particular profit increase."],"limits":["Practice data with undocumented currency and commercial provenance.","No repeat-customer or retention analysis is supported by the unique identifiers.","Source queries were inspected, not executed in a PostgreSQL instance during this design review."],"source":"https://github.com/Basit52692/SQL-Sales-Analysis/blob/main/sql/03_sales_trends.sql"},{"id":"python","number":"05","title":"Retail Analysis Pipeline","tool":"Python","types":["analytics","automation"],"kind":"Retail practice data","image":"assets/python.png","alt":"Original Python Matplotlib annual sales trend chart for 2019 to 2022, in source units.","cover":"Python / Original Matplotlib output","question":"How can analysis become repeatable, not just a one-off notebook?","subtitle":"A structured Python workflow from validated transactions to tables and charts.","tools":["Python","pandas","NumPy","Matplotlib","Jupyter"],"repo":"https://github.com/Basit52692/Python-Sales-Analysis","file":"https://basit52692.github.io/Basit-Hussain-Portfolio/assets/Python_Sales_Analysis_Professional.zip","fileLabel":"Python project","sourceLabel":"Original CSV, reusable source functions and chart outputs","chart":"retail","overview":["A Python project that turns a retail CSV into validated data, reusable summary tables and analytical charts. The structure separates source data, processed data, functions, notebooks and outputs.","It covers sales, profitability, regional/category contribution, shipping and discount behavior."],"dataset":["<strong>10,000 records</strong> for 2019–2022; 54,823 units. Total sales are 10,033,715.95 and total profit is 1,711,180.34 in source units.","The SQL project uses the same records. These are complementary technical approaches to one practice dataset, not separate client engagements."],"method":["Validate duplicates, missing source cells, identifier grain and shipping/order-date consistency.","Parse dates, derive time fields and shipping duration, and preserve valid negative-profit outcomes.","Compute KPI summaries and grouped analyses with pandas and NumPy; create charts with Matplotlib.","Write processed data and tabular outputs alongside reusable functions and a notebook. The embedded prototype chart recalculates yearly sums directly from the supplied raw CSV."],"findings":[{"title":"79 negative-profit orders are retained.","body":"Preserving them keeps genuine loss-making outcomes visible for investigation instead of treating them as cleaning errors."},{"title":"2020 has the highest annual sales in the snapshot.","body":"2,595,195.45 source units, compared with 2,535,711.07 in 2022. A recent positive growth rate does not mean a new period high."},{"title":"2022 profit is 438,023.59 source units.","body":"Use the Sales, Profit and Orders controls to compare different measures against the same yearly grain."}],"value":["A reproducible directory structure and exported outputs make the workflow easier to inspect, rerun and hand over.","The project demonstrates analytical process; no runtime benchmark, saved hours or employer impact has been measured here."],"limits":["The dataset is for practice and currency is unspecified.","All customer and product IDs are unique, so retention and true SKU claims would be misleading.","Discount findings are descriptive associations. The original Matplotlib chart uses a truncated sales axis; the interactive comparison here uses a zero baseline."],"source":"https://github.com/Basit52692/Python-Sales-Analysis/blob/main/data/raw/sales_orders.csv"}],"annual":[{"year":2019,"sales":2449522.47,"profit":417765.51,"orders":2431},{"year":2020,"sales":2595195.45,"profit":438245.42,"orders":2563},{"year":2021,"sales":2453286.96,"profit":417145.82,"orders":2489},{"year":2022,"sales":2535711.07,"profit":438023.59,"orders":2517}],"referrals":[{"name":"None","count":5400},{"name":"General Practice","count":1840},{"name":"Orthopedics","count":995},{"name":"Physiotherapy","count":276},{"name":"Cardiology","count":248},{"name":"Neurology","count":193},{"name":"Gastroenterology","count":178},{"name":"Renal","count":86}],"leadCounts":{"Needs Review":18,"Existing Website":78,"Potential Lead":54},"sqlSnippet":"WITH monthly_sales AS (\n    SELECT\n        DATE_TRUNC('month', order_date)::DATE AS month,\n        SUM(sales) AS sales\n    FROM sales_orders\n    GROUP BY 1\n),\nwith_previous AS (\n    SELECT\n        month,\n        sales,\n        LAG(sales) OVER (ORDER BY month) AS previous_month_sales\n    FROM monthly_sales\n)\nSELECT\n    month,\n    ROUND(sales, 2) AS sales,\n    ROUND(previous_month_sales, 2) AS previous_month_sales,\n    ROUND(100.0 * (sales - previous_month_sales) / NULLIF(previous_month_sales, 0), 2) AS mom_growth_pct\nFROM with_previous\nORDER BY month;","cvBase64":"","verification":{"rawLeads":168,"cleanLeads":150,"retailRows":10000,"retailSqlMatchesPython":true,"hospitalRows":9216,"hospitalSatisfactionNonempty":2517}};
